import{_ as r,C as s,o,c as n,j as t,a as i,E as d,ak as p}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse('{"title":"Probes","description":"Replay a passing test with one injected fault and record whether it noticed: client probes with piwi probe, the not-noticed gap, and experimental server probes.","frontmatter":{"title":"Probes","description":"Replay a passing test with one injected fault and record whether it noticed: client probes with piwi probe, the not-noticed gap, and experimental server probes.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/probes.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/probes.html"}],["meta",{"property":"og:title","content":"Probes | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Replay a passing test with one injected fault and record whether it noticed: client probes with piwi probe, the not-noticed gap, and experimental server probes."}]]},"headers":[],"relativePath":"features/probes.md","filePath":"features/probes.md","lastUpdated":1790850745000}'),h={name:"features/probes.md"};function c(l,e,u,b,g,m){const a=s("Needs");return o(),n("div",null,[e[0]||(e[0]=t("h1",{id:"probes",tabindex:"-1"},[i("Probes "),t("a",{class:"header-anchor",href:"#probes","aria-label":'Permalink to "Probes"'},"​")],-1)),d(a,{reporter:"",fixtures:""}),e[1]||(e[1]=p(`<p><a href="/guide/concepts.html#reach">Reach</a> says a test touched a route, not that it would fail if the route returned garbage, and many passing tests would not. A <strong><a href="/guide/concepts.html#probe">probe</a></strong> replays a passing test with one fault injected behind one request and records whether the test noticed. A route that stays green under a fault becomes a <strong>not noticed</strong> gap: the most dangerous class, because the suite says everything is fine.</p><h2 id="client-probes" tabindex="-1">Client probes <a class="header-anchor" href="#client-probes" aria-label="Permalink to &quot;Client probes&quot;">​</a></h2><p><code>piwi probe</code> runs the probe plan the dashboard computes for a project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> probe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project</span></span></code></pre></div><p>It fetches the plan, runs <code>playwright test</code> on the tests in it with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in probe mode, and posts each outcome back. The fixtures apply the fault at the Playwright boundary, on the matching response after the page&#39;s first navigation:</p><table tabindex="0"><thead><tr><th>Fault</th><th>What the test receives</th></tr></thead><tbody><tr><td><code>status-500</code></td><td>a 500 in place of the response</td></tr><tr><td><code>empty-body</code></td><td>the right status with an empty body</td></tr><tr><td><code>drop-field</code></td><td>the JSON body with its first field removed (from each element of an array)</td></tr><tr><td><code>stale-value</code></td><td>an earlier response to the same request in place of the current one</td></tr><tr><td><code>slow</code></td><td>the response five seconds late</td></tr></tbody></table><p>The plan pairs each passing test with a route it reaches: pairs never probed come first, then pairs whose test changed since its last probe, and each test gets one fault per run, up to a budget (50 pairs by default, <code>--budget</code> to change it). Quarantined tests and tests whose last run failed are left out. A fault that did not change the response records the pair as <em>inconclusive</em>, and an inconclusive pair waits a week before it returns to the plan.</p><p>A probe run is stamped as one, with retries off. It never counts as a real run: no failure clusters, no regression signals, no notifications, no pull-request feedback, no metric, no quarantine streak, never the baseline another run is compared with, and nothing in the Test Map but the probe outcomes. A probed test that notices its fault fails, so a non-zero Playwright exit is expected. The <a href="/reference/cli.html#probe">CLI reference</a> lists every flag.</p><h2 id="what-an-outcome-records" tabindex="-1">What an outcome records <a class="header-anchor" href="#what-an-outcome-records" aria-label="Permalink to &quot;What an outcome records&quot;">​</a></h2><p>Each outcome is a <em>checks</em> edge in the <a href="/features/scenario-gaps.html">Test Map</a> between the test and the route: noticed, not noticed, or inconclusive. The <em>not noticed</em> detector reads them: a route with at least one probe that no test noticed, and none that did, is a <strong>false-comfort</strong> gap:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tests pass when POST /api/orders breaks</span></span>
<span class="line"><span>A probe (status-500) on POST /api/orders did not make checkout › pay fail. Assert the effect the request should have.</span></span></code></pre></div><p>The next step is an assertion on what the request is for: the order appears, the total changes, the error shows. Once a probe on that route is noticed, the gap closes itself.</p><h2 id="server-probes" tabindex="-1">Server probes <a class="header-anchor" href="#server-probes" aria-label="Permalink to &quot;Server probes&quot;">​</a></h2><p><strong>Experimental.</strong> Server probes are off by default. The rule for when to turn them on (client probes reporting <em>not noticed</em> on one probed pair in ten) has not been measured yet. The design is in the <a href="https://github.com/PiwiTests/platform/blob/main/proposals/scenario-gaps.md#level-two--server-probes-m3-on-an-entry-condition" target="_blank" rel="noreferrer">scenario gaps proposal</a>.</p><p>A client probe rewrites the response in the browser, so the server never runs its error path. A server probe signs a fault onto one request (<code>X-Piwi-Probe</code>, an HMAC signature made with <code>PIWI_PROBE_SECRET</code>), and the <a href="/guide/backend-logs.html#server-probes">backend instrumentation</a> applies it inside the server: a thrown error, a status, a delay, a mutated response or a failed dependency call. The instrumentation reports the fault it applied, so a probe it did not honor records as <em>inconclusive</em>, never as a pass.</p><p>Two signals come back: whether the test noticed, as with a client probe, and whether the application coped. An uncaught exception, or a backend error with a blank page, is an <strong>unhandled</strong> finding; a console error, a dialog, a blank page or a backend error alone is <strong>degraded</strong>. Findings rank by severity and reach, and the <em>unprobed dependency</em> detector names the dependencies no probe has failed yet.</p><p>It needs:</p><ul><li>the Nitro plugin or the ASP.NET Core package in the application under test, with <code>PIWI_PROBE_SECRET</code> set and <code>PIWI_SERVER_PROBES=true</code>. Both apply faults only outside production. The ASP.NET Core package applies throw, status, delay and extreme-value faults; its data and dependency probes record as <em>inconclusive</em>;</li><li>the same <code>PIWI_PROBE_SECRET</code> where <code>piwi probe</code> runs;</li><li><strong>Server probes</strong> turned on in the project&#39;s edit page, where the fault classes and routes are allow-listed. Dependency faults on state-changing routes (<code>POST</code>, <code>PUT</code>, <code>PATCH</code>, <code>DELETE</code>) stay off unless you allow them.</li></ul><p>With server probes on, half of the budget goes to server faults.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/scenario-gaps.html">Scenario gaps &amp; the Test Map</a>: the other gap classes, and triage</li><li><a href="/guide/backend-logs.html">Backend instrumentation</a>: the packages server probes need</li><li><a href="/reference/cli.html#probe">Piwi CLI: probe</a>: every flag</li><li><a href="/reference/gap-detectors.html">Gap detectors &amp; exposure</a>: the <em>not noticed</em>, <em>unprobed dependency</em> and <em>not handled</em> detectors</li></ul>`,21))])}const y=r(h,[["render",c]]);export{w as __pageData,y as default};
